import React from "react";

const Hero = () => {
  return (
    <div className="hero">
      <h1>Welcome to EduSaarthi </h1>
      <p>Your Smart University Management Dashboard</p>

      <img
        src="https://cdn-icons-png.flaticon.com/512/3135/3135755.png"
        alt="student"
      />
    </div>
  );
};

export default Hero;
